  const next = { ...selected };
  // A configured machine stays selected from the Machines section even with no jobs there.
  const configured = new Set(projectMachineRows(p.machines, null).map(machine => machine.name));
  if (next.machine && !configured.has(next.machine) && !rows.some(row => row.machine === next.machine)) next.machine = null;
